package com.opensource.autonomous.agent.data

import com.google.gson.Gson
import com.google.gson.JsonSyntaxException
import com.google.gson.reflect.TypeToken
import java.util.UUID

/**
 * Expected JSON Schema matrix generated by the CEO Agent.
 * {
 *   "tasks": [
 *     { "assignedToAgentId": "2", "title": "...", "instruction": "..." }
 *   ]
 * }
 */
data class CeoMatrix(val tasks: List<CeoTaskItem>)
data class CeoTaskItem(val assignedToAgentId: String, val title: String, val instruction: String)

class MatrixParser(private val db: AppDatabase) {
    private val gson = Gson()

    /**
     * Parses the raw LLM output text, extracts the raw JSON contents, 
     * and maps them explicitly into actionable database entities.
     */
    suspend fun processCeoMatrix(rawLlmOutput: String): Result<Int> {
        return try {
            // Clean up any loose trailing text or conversational padding around the JSON array
            val jsonStartIndex = rawLlmOutput.indexOf("{")
            val jsonEndIndex = rawLlmOutput.lastIndexOf("}") + 1

            if (jsonStartIndex == -1 || jsonEndIndex == 0) {
                return Result.failure(IllegalArgumentException("Invalid response format: No structural matrix JSON block found."))
            }

            val sanitizedJson = rawLlmOutput.substring(jsonStartIndex, jsonEndIndex)
            val matrixType = object : TypeToken<CeoMatrix>() {}.type
            val matrixData: CeoMatrix = gson.fromJson(sanitizedJson, matrixType)

            var parsedCount = 0
            matrixData.tasks.forEach { item ->
                // Validate assigned agent range targets: 2 (Research) through 7 (Finance)
                val targetId = item.assignedToAgentId.trim()
                if (targetId.toIntOrNull() in 2..7) {
                    val taskEntity = TaskEntity(
                        id = UUID.randomUUID().toString(),
                        assignedToAgentId = targetId,
                        title = item.title,
                        instruction = item.instruction,
                        status = "PENDING",
                        result = null
                    )
                    db.taskDao().insertTask(taskEntity)

                    // Log the creation sequence back to the global thread
                    db.logDao().insertLog(LogEntity(agentId = "1", message = "CEO routed task out: ${item.title} to Agent $targetId"))
                    parsedCount++
                }
            }
            Result.success(parsedCount)
        } catch (e: JsonSyntaxException) {
            Result.failure(Exception("Matrix parsing schema mismatch syntax fault: ${e.localizedMessage}"))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}
